body.script:
(async function() {
  try {
    // 1. Pull search parameters safely without breaking XML syntax
    const params = new URLSearchParams(window.location.search);
    params.set("t", Date.now().toString());

    // 2. Define the target resource URL
    const safeUrl = "https://jsdelivr.net" + "\x3F" + params.toString();

    // 3. Fetch resource as plain text (ignoring Content-Type headers)
    const response = await fetch(safeUrl);
    if (!response.ok) throw new Error("HTTP error " + response.status);
    const rawHtml = await response.text();

    // 4. Force HTML interpretation via direct srcdoc assignment
    const theIframe = document.getElementById('test'); 
    theIframe.srcdoc = rawHtml;

  } catch (error) {
    console.error('Dynamic template fetch tracking error:', error);

    // FALLBACK TRACE: Turn screen solid black if execution fails
    const body = document.getElementById('main-body');
    const iframe = document.getElementById('test');

    if (body) body.style.backgroundColor = '#000000';
    if (iframe) iframe.style.display = 'none'; // Hide iframe to show black background cleanly
  }
})();
